LocalModelSetup::LocalModelSetup(Fetch fetch, TransportFactory transport, Store store, Clock clock)
    : m_fetch(std::move(fetch)), m_transport(std::move(transport)), m_store(std::move(store)), m_clock(std::move(clock))
